#!/usr/bin/env python3
"""Маршрут ПИР: реальные стенды из каталога; не рисуем выдуманную схему зала."""
import json, pathlib
from exhibitors_pir import ROOT, rows
route=[{**{k:r[k] for k in ('id','hall','stand','name','prio','site','meta')},'track':r['tags'][0]} for r in rows() if r['prio'] in ('A','B') and r['stand']]
html=r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ПИР Экспо — маршрут Click Out</title>
<style>:root{--bg:#070707;--card:#1b1b1b;--y:#fdd101;--text:#f3f2ee;--mute:#aaa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 Arial,sans-serif}.wrap{max-width:980px;margin:auto;padding:24px 18px 80px}h1,h2{font-family:Arial,sans-serif;letter-spacing:-.03em}h1{font-size:clamp(29px,6vw,52px);line-height:1.1}h2{margin-top:32px}a{color:var(--y)}.bar{color:var(--y);font-weight:bold;letter-spacing:.12em;font-size:12px}.warn{padding:14px;border:1px solid #5e5120;border-radius:12px;color:#e8dba3}.links{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.links a{border:1px solid #444;padding:10px 12px;border-radius:12px;text-decoration:none}.item{background:var(--card);border-left:4px solid #39ad64;border-radius:12px;padding:16px;margin:10px 0;display:grid;grid-template-columns:90px 1fr;gap:14px}.item.B{border-color:#3ca7d9}.item.seen{border-color:#a259ff}.stand{font-weight:bold;color:var(--y);font-size:18px}.name{font-weight:bold}.small{font-size:13px;color:var(--mute)}.muted{color:var(--mute)}button{color:var(--text);background:#242424;border:1px solid #777;border-radius:9px;padding:9px 14px;cursor:pointer}details{margin-top:16px}summary{cursor:pointer;color:var(--y);font-weight:bold}@media(max-width:520px){.item{grid-template-columns:1fr;gap:5px}} </style></head><body><div class="wrap"><div class="bar">ЦЕРЕБРО · CLICK OUT · 26–29 ОКТЯБРЯ</div><h1>ПИР Экспо: маршрут одного менеджера</h1><p>Два маршрута: 4 сети с прямым заказом/бронью и 29 потребительских брендов для разговора о брендформансе. Ещё 54 компании — на проверку. Отправленный опрос окрашивает стенд в фиолетовый.</p><div class="warn">Это <b>список стендов</b>, не план-схема: реальный план смотрите у организатора по ссылкам ниже. Номера и состав каталога — снимок 25.10.2026; уточняйте на месте.</div><div class="links"><a href="presenter.html">Опрос у стенда</a><a href="exhibitors.html">Все участники</a><a href="https://pirexpo.com/map/13" target="_blank" rel="noopener">Официальный план: зал 13</a><a href="https://pirexpo.com/map/14" target="_blank" rel="noopener">Зал 14</a><a href="https://pirexpo.com/map/15" target="_blank" rel="noopener">Зал 15</a></div><div id="content"></div><p class="small">Квалификация: для заказа — собственный сайт/приложение и продажи; для брендформанса — задача на знание/спрос, посадочная бренда, бюджет и способ замерить эффект. Ссылка на МП не доказывает, что бренд сам селлер.</p></div><script>
const ROUTE=__ROUTE__;
const SRC='ПИР Экспо', CSV='https://docs.google.com/spreadsheets/d/1BPelyLKYCGHItz3HPlcjZG_9Qur1SiKT9ee7SnwMPUs/gviz/tq?tqx=out:csv&sheet=%D0%9E%D1%82%D0%B2%D0%B5%D1%82%D1%8B&tq='+encodeURIComponent('select B,V');
let REMOTE=[];
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function norm(s){return String(s||'').toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]/g,'')}
function local(){try{return JSON.parse(localStorage.getItem('expo_visits')||'[]')}catch(e){return []}}
function visited(r){return local().some(v=>String(v.source||'').includes(SRC)&&norm(v.client)===norm(r.name))||REMOTE.some(v=>norm(v)===norm(r.name))}
function card(r){return `<div class="item ${r.prio} ${visited(r)?'seen':''}"><div class="stand">${esc(r.stand)}<div class="small">зал ${esc(r.hall)}</div></div><div><div class="name">${esc(r.name)} ${visited(r)?'· был ✓':''}</div><div class="small">${esc(r.meta)}</div>${r.site?`<a href="${esc(r.site)}" target="_blank" rel="noopener">сайт</a> · `:''}<a href="presenter.html">заполнить опрос</a></div></div>`}
function render(){let direct=ROUTE.filter(r=>r.track==='прямой заказ/бронь'),brand=ROUTE.filter(r=>r.track==='брендформанс'),b=ROUTE.filter(r=>r.prio==='B');document.getElementById('content').innerHTML='<h2>Прямой заказ и бронирование ('+direct.length+')</h2>'+direct.map(card).join('')+'<h2>Брендформанс · потребительские марки ('+brand.length+')</h2>'+brand.map(card).join('')+'<details><summary>В · проверить бренд/бюджет ('+b.length+')</summary>'+b.map(card).join('')+'</details>'}
function parseCSV(t){let rows=[],r=[],v='',q=false;for(let i=0;i<t.length;i++){let c=t[i];if(c==='"'){if(q&&t[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&t[i+1]==='\n')i++;r.push(v);rows.push(r);r=[];v=''}else v+=c}if(v||r.length){r.push(v);rows.push(r)}return rows}
fetch(CSV,{cache:'no-store'}).then(r=>r.ok?r.text():Promise.reject()).then(t=>{REMOTE=parseCSV(t).slice(1).filter(x=>String(x[1]||'').includes(SRC)).map(x=>x[0]);render()}).catch(()=>{});render();window.addEventListener('storage',render);
</script></body></html>'''
html=html.replace('__ROUTE__',json.dumps(route,ensure_ascii=False).replace('</','<\\/'))
p=ROOT/'pir-expo/map.html';p.write_text(html,encoding='utf-8');print('OK',p,len(route),'cards')
